#define MAX_BOWLS 5

int bowls[MAX_BOWLS];
int top = 0;

int is_full(void) { return top == MAX_BOWLS; }
int is_empty(void) { return top == 0; }

int push(int value) {
    if (is_full()) {
        return 0;
